// Counts frames where the visible frame is NOT fully covered by mounted rows during a flick.
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage({ viewport: { width: 1200, height: 900 } });
  await p.goto('http://localhost:5190/'); await p.waitForTimeout(800);
  await p.locator('nav button', { hasText: 'Virtual Scroller on Lenis' }).click(); await p.waitForTimeout(1200);
  const frame = p.locator('.virtual-scroller').first(); const bb = await frame.boundingBox();
  await p.mouse.move(bb.x + bb.width / 2, bb.y + bb.height / 2);
  const results = [];
  for (const notches of [2000, 4000, 8000]) {
    // arm the sampler, then flick
    const sampling = p.evaluate(() => new Promise((resolve) => {
      const frame = document.querySelector('.virtual-scroller'); const fr = frame.getBoundingClientRect();
      let frames = 0, uncovered = 0, maxGap = 0, mountedMax = 0; const t0 = performance.now();
      const tick = () => {
        const rows = [...frame.querySelectorAll('.virtual-scroller__item')];
        if (rows.length) {
          mountedMax = Math.max(mountedMax, rows.length);
          const top = Math.min(...rows.map((r) => r.getBoundingClientRect().top));
          const bottom = Math.max(...rows.map((r) => r.getBoundingClientRect().bottom));
          const gap = Math.max(0, fr.bottom - bottom, top - fr.top);
          if (gap > 1) { uncovered++; maxGap = Math.max(maxGap, gap); }
        }
        frames++;
        if (performance.now() - t0 < 1500) requestAnimationFrame(tick); else resolve({ frames, uncovered, maxGap: Math.round(maxGap), mountedMax });
      };
      requestAnimationFrame(tick);
    }));
    await p.waitForTimeout(50);
    for (let i = 0; i < 4; i++) { await p.mouse.wheel(0, notches / 4); await p.waitForTimeout(16); }
    results.push({ notches, ...(await sampling) });
    await p.waitForTimeout(600);
  }
  console.table(results); await b.close();
