test('shrinking the list drops the measurements past its end and re-derives the extent', async () => {
  const items = ref(rows(10));
  const emit = vi.fn();
  const props = {
    ...VirtualScroller.Class.propsDefaults,
    assumedSize: 30,
    get modelValue() {
      return items.value;
    }
