/*
=== GENERATOR ===
Goal: Let a finger select text in a list where a drag already means scroll, by promoting a still hold into a selection and handing the moves to the owner as points.
[Touch events keep firing on the node the finger landed on](virtual-scroller.invariants.md#touch-events-keep-firing-on-the-node-the-finger-landed-on)
[A long press turns the next move into a selection](virtual-scroller.invariants.md#a-long-press-turns-the-next-move-into-a-selection)
[A hosted capability reaches its owner through an interface](virtual-scroller.invariants.md#a-hosted-capability-reaches-its-owner-through-an-interface)
// domain-invariant: $TouchSelectionGesture — If the finger moves past the slop before the hold fires, then the gesture is a scroll and the owner never hears of it.
// domain-invariant: $TouchSelectionGesture — If two fingers land, then no hold arms; if a second finger lands mid-drag, then the first finger keeps the focus.
// domain-invariant: $TouchSelectionGesture — If the finger lifts after a selecting drag, then the drag ends and the copy chip shows exactly when the owner holds a selection.
Impossible if true: The page scrolling while a touch selection is being extended.

=== GENERATOR-DESCRIPTION-NOTE
(none)
=== GENERATOR-DESCRIBED ===
The owner is a plain object of the three primitives plus hasSelection,
recording every call. Timers are faked so the long press is a clock
advance, not a wait. Touch events are plain Events with a `touches` list
attached, dispatched on real jsdom nodes — including a node removed from
the document, which is the whole reason the listeners ride the origin
node instead of the element.
*/

import { afterEach, beforeEach, expect, test, vi } from 'vitest';
import { TouchSelectionGesture } from './TouchSelectionGesture';

const Gesture = TouchSelectionGesture.Class;

function touchEvent(type: string, touches: { x: number; y: number; id?: number }[]) {
  const event = new Event(type, { bubbles: true, cancelable: true });
  Object.defineProperty(event, 'touches', {
    value: touches.map((touch) => ({
      clientX: touch.x,
      clientY: touch.y,
      identifier: touch.id ?? 1
    }))
  });
  return event as Event & { lenisStopPropagation?: boolean };
}

function gesture() {
  const owner = {
    beginAt: vi.fn(() => true),
    extendTo: vi.fn(),
    endDrag: vi.fn(),
    hasSelection: false
  };
  const instance = new Gesture(owner);
  const element = document.createElement('div');
  const row = document.createElement('div');
  element.appendChild(row);
  document.body.appendChild(element);
  instance.attach(element);
  return { owner, instance, element, row };
}

beforeEach(() => vi.useFakeTimers());
afterEach(() => {
  vi.useRealTimers();
  document.body.innerHTML = '';
});

// domain-invariant: $TouchSelectionGesture — If the finger moves past the slop before the hold fires, then the gesture is a scroll and the owner never hears of it.
test('movement within the slop keeps the hold alive; past it, the gesture is a scroll', () => {
  expect(Gesture.exceedsSlop(0)).toBe(false);
  expect(Gesture.exceedsSlop(Gesture.SLOP_PX)).toBe(false);
  expect(Gesture.exceedsSlop(Gesture.SLOP_PX + 0.1)).toBe(true);
  expect(Gesture.distanceFrom({ x: 10, y: 10 }, 13, 14)).toBe(5);
  expect(Gesture.distanceFrom({ x: 10, y: 10 }, 7, 6)).toBe(5);

  const { owner, instance, row } = gesture();
  row.dispatchEvent(touchEvent('touchstart', [{ x: 100, y: 100 }]));
  row.dispatchEvent(touchEvent('touchmove', [{ x: 104, y: 103 }]));
  vi.advanceTimersByTime(Gesture.LONG_PRESS_MS / 2);
  row.dispatchEvent(touchEvent('touchmove', [{ x: 100, y: 130 }]));
  vi.advanceTimersByTime(Gesture.LONG_PRESS_MS);
  expect(owner.beginAt).not.toHaveBeenCalled();
  expect(instance.selecting.value).toBe(false);
  instance.dispose();
});

// invariant: A long press turns the next move into a selection (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
// impossible-if-true: $TouchSelectionGesture — The page scrolling while a touch selection is being extended.
test('a still hold promotes at the long-press mark, and every move after it extends the selection while the page and the list are told to stay put', () => {
  const { owner, instance, row } = gesture();
  row.dispatchEvent(touchEvent('touchstart', [{ x: 100, y: 100 }]));
  vi.advanceTimersByTime(Gesture.LONG_PRESS_MS - 1);
  expect(owner.beginAt).not.toHaveBeenCalled();
  vi.advanceTimersByTime(1);
  expect(owner.beginAt).toHaveBeenCalledWith(100, 100);
  expect(instance.selecting.value).toBe(true);

  const move = touchEvent('touchmove', [{ x: 100, y: 180 }]);
  row.dispatchEvent(move);
  expect(owner.extendTo).toHaveBeenCalledWith(100, 180);
  expect(move.defaultPrevented).toBe(true);
  expect(move.lenisStopPropagation).toBe(true);
  instance.dispose();
});

// invariant: Touch events keep firing on the node the finger landed on (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
test('a finger whose origin row left the DOM still extends the selection, because the listeners ride the origin node', () => {
  const { owner, instance, row } = gesture();
  row.dispatchEvent(touchEvent('touchstart', [{ x: 100, y: 100 }]));
  vi.advanceTimersByTime(Gesture.LONG_PRESS_MS);
  row.remove();
  expect(row.isConnected).toBe(false);
  row.dispatchEvent(touchEvent('touchmove', [{ x: 100, y: 190 }]));
  expect(owner.extendTo).toHaveBeenLastCalledWith(100, 190);
  instance.dispose();
});

// domain-invariant: $TouchSelectionGesture — If two fingers land, then no hold arms; if a second finger lands mid-drag, then the first finger keeps the focus.
test('two fingers never arm a hold, and a second finger mid-drag does not steal the focus', () => {
  const pinch = gesture();
  pinch.row.dispatchEvent(
    touchEvent('touchstart', [
      { x: 100, y: 100, id: 1 },
      { x: 200, y: 100, id: 2 }
    ])
  );
  vi.advanceTimersByTime(Gesture.LONG_PRESS_MS);
  expect(pinch.owner.beginAt).not.toHaveBeenCalled();
  pinch.instance.dispose();

  const { owner, instance, row } = gesture();
  row.dispatchEvent(touchEvent('touchstart', [{ x: 100, y: 100, id: 1 }]));
  vi.advanceTimersByTime(Gesture.LONG_PRESS_MS);
  row.dispatchEvent(
    touchEvent('touchmove', [
      { x: 100, y: 150, id: 1 },
      { x: 300, y: 300, id: 2 }
    ])
  );
  expect(owner.extendTo).toHaveBeenLastCalledWith(100, 150);
  // Only the second finger reported: the tracked one is absent, nothing moves.
  row.dispatchEvent(touchEvent('touchmove', [{ x: 300, y: 320, id: 2 }]));
  expect(owner.extendTo).toHaveBeenCalledTimes(1);
  instance.dispose();
});

// domain-invariant: $TouchSelectionGesture — If the finger lifts after a selecting drag, then the drag ends and the copy chip shows exactly when the owner holds a selection.
// invariant: A hosted capability reaches its owner through an interface (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
test('lifting the finger ends the drag and reports selected exactly when the owner holds a selection; a cleared selection drops the chip', () => {
  const { owner, instance, row } = gesture();
  row.dispatchEvent(touchEvent('touchstart', [{ x: 100, y: 100 }]));
  vi.advanceTimersByTime(Gesture.LONG_PRESS_MS);
  row.dispatchEvent(touchEvent('touchmove', [{ x: 100, y: 180 }]));
  owner.hasSelection = true;
  row.dispatchEvent(touchEvent('touchend', []));
  expect(owner.endDrag).toHaveBeenCalledTimes(1);
  expect(instance.selecting.value).toBe(false);
  expect(instance.selected.value).toBe(true);

  instance.onSelectionCleared();
  expect(instance.selected.value).toBe(false);

  // A tap (no hold) ends nothing.
  row.dispatchEvent(touchEvent('touchstart', [{ x: 100, y: 100 }]));
  row.dispatchEvent(touchEvent('touchend', []));
  expect(owner.endDrag).toHaveBeenCalledTimes(1);
  instance.dispose();
});

/*
=== GENERATOR ===
Goal: Size the rows mounted beyond the visible window from the motion itself, so a flick never shows canvas and a resting list never carries a flick's pad.
[The transform lerps to the target over many frames](virtual-scroller.invariants.md#the-transform-lerps-to-the-target-over-many-frames)
[The pad covers the lerp gap exactly](virtual-scroller.invariants.md#the-pad-covers-the-lerp-gap-exactly)
[Lenis is read inside the walk never tracked](virtual-scroller.invariants.md#lenis-is-read-inside-the-walk-never-tracked)
[A pad never outlives its flick](virtual-scroller.invariants.md#a-pad-never-outlives-its-flick)
[A hosted capability reaches its owner through an interface](virtual-scroller.invariants.md#a-hosted-capability-reaches-its-owner-through-an-interface)
// domain-invariant: $VirtualScrollerPadding — If the content moves at a speed, then the rows ahead cover the distance it travels in the lookahead, rounded up and capped, and a crawl counts as still.
// domain-invariant: $VirtualScrollerPadding — If a pad is split, then the lookahead rows sit on the end the content moves toward and the gap rows on the end it comes from; at rest both ends carry the base.
// domain-invariant: $VirtualScrollerPadding — If a new reading arrives, then a higher level replaces the held one at once, a lower one only after the settle window, and a reversal drops it immediately.
Impossible if true: A pad that shrinks on the first frame of a flick's decay.

=== GENERATOR-DESCRIBED ===
The owner is a plain object of the four fields the pad reads; the walk
is a call to pad() with an explicit clock, so the hysteresis is a
sequence of readings, not a wait. Timers are faked for the settle
re-walk, and the settled version is read directly — in the scroller it
is read inside the window walk, which is what makes the bump rerun it.
*/

import { afterEach, beforeEach, expect, test, vi } from 'vitest';
import { VirtualScrollerPadding } from './VirtualScrollerPadding';

const Logic = VirtualScrollerPadding.Class;

beforeEach(() => vi.useFakeTimers());
afterEach(() => vi.useRealTimers());

// domain-invariant: $VirtualScrollerPadding — If the content moves at a speed, then the rows ahead cover the distance it travels in the lookahead, rounded up and capped, and a crawl counts as still.
test('rows ahead cover the distance the content travels in the lookahead, rounded up and capped, and a crawl is still', () => {
  // 40 px/frame at 16.7 ms/frame over 250 ms ≈ 599 px; 40 px rows → 15 rows.
  expect(Logic.rowsAhead(40, 40)).toBe(15);
  expect(Logic.rowsAhead(-40, 40)).toBe(15);
  expect(Logic.rowsAhead(0.2, 40)).toBe(0);
  expect(Logic.rowsAhead(10_000, 40)).toBe(Logic.MAX_ROWS_AHEAD);
  expect(Logic.rowsAhead(40, 0)).toBe(0);
  expect(Logic.directionOf(3)).toBe(1);
  expect(Logic.directionOf(-3)).toBe(-1);
  expect(Logic.directionOf(0.1)).toBe(0);
});

// invariant: The pad covers the lerp gap exactly (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
// invariant: The transform lerps to the target over many frames (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
test('rows behind cover the lerp gap exactly, rounded up and capped', () => {
  expect(Logic.rowsBehind(848, 56)).toBe(16);
  expect(Logic.rowsBehind(-848, 56)).toBe(16);
  expect(Logic.rowsBehind(0, 56)).toBe(0);
  expect(Logic.rowsBehind(1_000_000, 56)).toBe(Logic.MAX_ROWS_GAP);
});

// domain-invariant: $VirtualScrollerPadding — If a pad is split, then the lookahead rows sit on the end the content moves toward and the gap rows on the end it comes from; at rest both ends carry the base.
test('the split puts the lookahead rows ahead of the motion and the gap rows behind it', () => {
  expect(Logic.split(3, 12, 16, 1)).toEqual({ before: 19, after: 15 });
  expect(Logic.split(3, 12, 16, -1)).toEqual({ before: 15, after: 19 });
  expect(Logic.split(3, 12, 16, 0)).toEqual({ before: 3, after: 3 });
});

// domain-invariant: $VirtualScrollerPadding — If a new reading arrives, then a higher level replaces the held one at once, a lower one only after the settle window, and a reversal drops it immediately.
// impossible-if-true: $VirtualScrollerPadding — A pad that shrinks on the first frame of a flick's decay.
test('settle grows at once, shrinks only after the settle window, and drops on a turn', () => {
  const start = { ahead: 0, direction: 0 as const, since: 0 };
  const grown = Logic.settle(start, 10, 1, 100);
  expect(grown).toEqual({ ahead: 10, direction: 1, since: 100 });
  // The first lower reading of the decay keeps the held level.
  expect(Logic.settle(grown, 4, 1, 101)).toBe(grown);
  expect(Logic.settle(grown, 4, 1, 100 + Logic.SETTLE_MS - 1)).toBe(grown);
  // Once the window passes, the lower reading takes over.
  expect(Logic.settle(grown, 4, 1, 100 + Logic.SETTLE_MS)).toEqual({
    ahead: 4,
    direction: 1,
    since: 100 + Logic.SETTLE_MS
  });
  // A reversal drops to the new reading immediately — the held rows face the wrong way.
  expect(Logic.settle(grown, 2, -1, 150)).toEqual({ ahead: 2, direction: -1, since: 150 });
  // Coming to rest keeps the direction the rows already face.
  expect(Logic.settle(grown, 0, 0, 100 + Logic.SETTLE_MS)).toEqual({
    ahead: 0,
    direction: 1,
    since: 100 + Logic.SETTLE_MS
  });
});

// invariant: A hosted capability reaches its owner through an interface (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
// invariant: Lenis is read inside the walk never tracked (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
test('pad() follows the lerp gap frame by frame and holds the lookahead across a decaying tail, reading the owner each call', () => {
  const owner = { halfPaddingQuantity: 3, scrollVelocity: 40, scrollGap: 800, estimatedItemSize: 40 };
  const padding = new Logic(owner);
  // Flick: 20 rows of gap behind the target-anchored window, 15 of lookahead beyond it.
  expect(padding.pad(0)).toEqual({ before: 23, after: 18 });
  // The lerp converges: the gap shrinks at once, the lookahead is held.
  owner.scrollVelocity = 8;
  owner.scrollGap = 80;
  expect(padding.pad(100)).toEqual({ before: 5, after: 18 });
  // Settled: the lookahead drops to the reading.
  owner.scrollGap = 0;
  expect(padding.pad(100 + Logic.SETTLE_MS)).toEqual({ before: 3, after: 6 });
  // A flick back: everything mirrors.
  owner.scrollVelocity = -40;
  owner.scrollGap = -800;
  expect(padding.pad(1000)).toEqual({ before: 18, after: 23 });
  expect(padding.rowsAhead).toBe(15);
  expect(padding.before).toBe(18);
  expect(padding.after).toBe(23);
  padding.dispose();
});

// invariant: A pad never outlives its flick (examples/playground/src/examples/virtual-scroller/virtual-scroller.invariants.md)
test('a walk that pads beyond the base arms one more walk after the settle window; a base walk arms nothing; dispose cancels', () => {
  const owner = { halfPaddingQuantity: 3, scrollVelocity: 40, scrollGap: 0, estimatedItemSize: 40 };
  const padding = new Logic(owner);
  expect(padding.settledVersion.value).toBe(0);
  padding.pad(0);
  vi.advanceTimersByTime(Logic.SETTLE_MS + 49);
  expect(padding.settledVersion.value).toBe(0);
  vi.advanceTimersByTime(1);
  expect(padding.settledVersion.value).toBe(1);

  // At rest the walk pads the base only, so no timer is armed.
  owner.scrollVelocity = 0;
  padding.pad(10_000);
  vi.advanceTimersByTime(Logic.SETTLE_MS + 100);
  expect(padding.settledVersion.value).toBe(1);

  // A flick, then dispose before the window: the bump never comes.
  owner.scrollVelocity = 40;
  padding.pad(20_000);
  padding.dispose();
  vi.advanceTimersByTime(Logic.SETTLE_MS + 100);
  expect(padding.settledVersion.value).toBe(1);
});

/*
=== GENERATOR ===
Goal: Drive the demo's million-row list from a few shared strings and a speed slider, so the page stays memory-sane and every control is a name on the class.
// domain-invariant: $VirtualScrollerExample — If the rows are built, then every body is one of twenty-four shared strings, the id is the index and the position is one-based.
// domain-invariant: $VirtualScrollerExample — If a row's text is asked, then it is the same string the template renders: the locale position, a dash, the body.
// domain-invariant: $VirtualScrollerExample — If the speed slider reads px per second, then the creep knob reads ms per px with a floor of one px per second.
// domain-invariant: $VirtualScrollerExample — If a control fires, then it delegates to the scroller's exposed instance: jump with a 12 px top offset, play from zero delay, pause.
Impossible if true: A million unique body strings.

=== GENERATOR-DESCRIBED ===
The million-row count is a static, so a subclass overrides it to a
thousand for the spec: the same class, a smaller list. The scroller is
a plain object standing in for the template ref — the controls are
delegations, and the double records where they land.
*/

import { ref } from 'vue';
import { expect, test, vi } from 'vitest';
import { Reactive } from '../../ivue';
import { Static } from '../../Static';
import { VirtualScrollerExample } from './VirtualScrollerExample';

class $Small extends VirtualScrollerExample.$Class {
  static override readonly ITEM_COUNT = 1000;
}

namespace Small {
  export const $Class = Static($Small);
  export let Class = Reactive($Class);
}

// domain-invariant: $VirtualScrollerExample — If the rows are built, then every body is one of twenty-four shared strings, the id is the index and the position is one-based.
// impossible-if-true: $VirtualScrollerExample — A million unique body strings.
test('a thousand rows share twenty-four body strings, with index ids and one-based positions', () => {
  const example = new Small.Class();
  const items = example.items.value as VirtualScrollerExample.Row[];
  expect(items).toHaveLength(1000);
  expect(new Set(items.map((row) => row.body)).size).toBe(24);
  expect(items[0]).toMatchObject({ id: '0', position: '1' });
  expect(items[999]).toMatchObject({ id: '999', position: '1000' });
  expect(example.itemCount).toBe(1000);
  expect(example.itemCountLabel).toBe((1000).toLocaleString());
});

// domain-invariant: $VirtualScrollerExample — If a row's text is asked, then it is the same string the template renders: the locale position, a dash, the body.
test('a row’s copy text is the locale position, a dash, and the body', () => {
  const example = new Small.Class();
  const row = { id: '1233', position: '1234', body: 'The window walks.' } as VirtualScrollerExample.Row;
  expect(example.rowText(row)).toBe(`#${(1234).toLocaleString()} — The window walks.`);
});

// domain-invariant: $VirtualScrollerExample — If the speed slider reads px per second, then the creep knob reads ms per px with a floor of one px per second.
test('the speed slider’s px per second becomes the creep’s ms per px, floored at one px per second', () => {
  const example = new Small.Class();
